14	// openLaunchForm fetches exposed ports then opens the launch form
15	func (m Model) openLaunchForm() (tea.Model, tea.Cmd) {
16		img := m.getSelectedImage()
17		if img == nil {
18			return m, nil
19		}
20		name := img.Name()
21		return m, fetchImageExposedPortsCmd(name)
22	}
23	
24	// getSelectedImage returns the selected image or nil.
25	//
26	// The cursor is resolved against the very slice the rows were built from, so it
27	// cannot point at one ordering while the screen shows another.
28	func (m Model) getSelectedImage() *docker.Image {
29		row, ok := m.imageTable.Selected()
30		if !ok {
31			return nil
32		}
33		return &row.Image
34	}
35	
36	// deleteSelectedImage shows confirm modal for deletion
37	func (m Model) deleteSelectedImage() (tea.Model, tea.Cmd) {
38		img := m.getSelectedImage()
39		if img == nil {
40			return m, nil
41		}
42		name := img.Name()
43		if m.imageTable.IsBusy(img.ID) {
44			return m, m.footer.Warn(busyMessage)
45		}
46		m.pendingAction = "delete-image"
47		m.confirmModal = sharedcomponents.NewConfirmModal("Delete Image", fmt.Sprintf("Delete '%s'?", name))
48		return m, nil
49	}
50	
51	// pruneImages shows confirm modal for pruning
52	func (m Model) pruneImages() (tea.Model, tea.Cmd) {
53		m.pendingAction = "prune-images"
54		m.confirmModal = sharedcomponents.NewConfirmModal("Prune Images", "Remove all dangling (unused) images?")
55		return m, nil
56	}
57	
58	// scanSelectedImage launches a scan for the selected image using saved options
59	func (m Model) scanSelectedImage() (tea.Model, tea.Cmd) {
60		img := m.getSelectedImage()
61		if img == nil {
62			return m, nil
63		}
64		name := img.Name()
65		if m.scanningImage(name) {
66			return m, m.footer.Warn("Scan already in progress")
67		}
68		return m, jobs.Start(
69			m.scanRun([]string{name}),
70			batchScanCmd([]imageScanJob{{Name: name, Target: img.ScanTarget()}}, scan.OptionsFromConfig(m.config)),
71		)
72	}
73	
74	// scanAllUnscanned triggers batch scanning of all unscanned images using config defaults
75	// confirmScanAll asks before scanning every image, and the purge is the modal's
76	// checkbox rather than a second key.
77	//
78	// A and ctrl+a differed only by a modifier, and nothing in their shape said
79	// which one purged the cache — the closest this application came to losing data
80	// by accident (§3.26). The destructive half is a deliberate gesture now.
81	func (m Model) confirmScanAll() (tea.Model, tea.Cmd) {
82		if m.anyScanRunning() {
83			return m, m.footer.Warn("A scan is already running")
84		}
85		m.scanAllModal = sharedcomponents.NewOptionConfirmModal(
86			"Scan All",
87			"Scan every image in this list?",
88			"Purge cached results first (rescans everything)",
89		)
90		return m, nil
91	}
92	
93	// scanAll scans the whole list when the cache was purged, and only what has
94	// never been scanned otherwise.
95	func (m Model) scanAll(purge bool) (tea.Model, tea.Cmd) {
96		if purge {
97			return m.requestScanAll()
98		}
99		return m.scanAllUnscanned()
100	}
101	
102	func (m Model) scanAllUnscanned() (tea.Model, tea.Cmd) {
103		if m.anyScanRunning() {
104			return m, nil
105		}
106		var queue []imageScanJob
107		for _, img := range m.images {
108			if img.Repository == "<none>" {
109				continue
110			}
111			name := img.Name()
112			if _, ok := m.scanCache[name]; !ok {
113				queue = append(queue, imageScanJob{Name: name, Target: img.ScanTarget()})
114			}
115		}
116		if len(queue) == 0 {
117			return m, m.footer.Warn("All images are already scanned")
118		}
119		return m, jobs.Start(
120			m.scanRun(jobNames(queue)),
121			batchScanCmd(queue, scan.OptionsFromConfig(m.config)),
122		)
123	}
124	
125	// requestScanAll launches a batch scan for all images with the configured options.
126	// Rule 126: purges the in-memory and disk cache before scanning.
127	func (m Model) requestScanAll() (tea.Model, tea.Cmd) {
128		if m.anyScanRunning() {
129			return m, nil
130		}
131		var queue []imageScanJob
132		var cacheKeys []string
133		for _, img := range m.images {
134			if img.Repository == "<none>" {
135				continue
136			}
137			name := img.Name()
138			queue = append(queue, imageScanJob{Name: name, Target: img.ScanTarget()})
139			cacheKeys = append(cacheKeys, name)
140			delete(m.scanCache, name)
141		}
142		if len(queue) == 0 {
143			return m, nil
144		}
145		return m, tea.Batch(
146			deleteScanCacheCmd(cacheKeys),
147			jobs.Start(m.scanRun(cacheKeys), batchScanCmd(queue, scan.OptionsFromConfig(m.config))),
148		)
149	}
150	
151	// handleImageScanStarting drops whatever the footer still said about the last
152	// attempt.
153	//
154	// The row is already spinning: the router recorded the transition before handing
155	// the message on, and the snapshot that carried it rebuilt the table. There is
156	// no chain to restart either — the router holds the only one (D5).
157	func (m Model) handleImageScanStarting(_ ImageScanStartingMsg) (tea.Model, tea.Cmd) {
158		m.footer.Clear()
159		return m, nil
160	}
161	
162	// handleImageScanFinished updates scan results for a completed image scan.
163	func (m Model) handleImageScanFinished(msg ImageScanFinishedMsg) (tea.Model, tea.Cmd) {
164		if msg.Err != nil {
165			m.failedScans[msg.ImageName] = true
166		} else {
167			delete(m.failedScans, msg.ImageName)
168			m.scanCache[msg.ImageName] = msg.Entry
169			m.footer.Clear()
170		}
171		m.updateImageTable()
172		if m.registryBrowser != nil {
173			m.registryBrowser.SetScanCache(m.scanCache)
174		}
175		return m, nil
176	}
177	
178	// handleScanRequest rescans one image by name, whoever asked.
179	//
180	// The router sends this when a cached scan's stored result has gone missing:
181	// the row is still in the list, and the scan that would replace it belongs
182	// here, next to the cache it writes. The name is both the cache key and the
183	// scan target, as it is for an image typed rather than picked.
184	func (m Model) handleScanRequest(msg ScanRequestMsg) (tea.Model, tea.Cmd) {
185		if msg.ImageName == "" || m.scanningImage(msg.ImageName) {
186			return m, nil
187		}
188		job := imageScanJob{Name: msg.ImageName, Target: msg.ImageName}
189		return m, jobs.Start(
190			m.scanRun([]string{msg.ImageName}),
191			batchScanCmd([]imageScanJob{job}, scan.OptionsFromConfig(m.config)),
192		)
193	}
194	
195	// jobNames is the target list of a queue of scan jobs, in order.
196	func jobNames(queue []imageScanJob) []string {
197		out := make([]string, 0, len(queue))
198		for _, job := range queue {
199			out = append(out, job.Name)
200		}
201		return out
202	}
