package ociresources

import (
	"fmt"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// openLaunchForm fetches exposed ports then opens the launch form
func (m Model) openLaunchForm() (tea.Model, tea.Cmd) {
	img := m.getSelectedImage()
	if img == nil {
		return m, nil
	}
	name := img.Name()
	return m, fetchImageExposedPortsCmd(name)
}

// getSelectedImage returns the selected image or nil.
//
// The cursor is resolved against the very slice the rows were built from, so it
// cannot point at one ordering while the screen shows another.
func (m Model) getSelectedImage() *docker.Image {
	row, ok := m.imageTable.Selected()
	if !ok {
		return nil
	}
	return &row.Image
}

// deleteSelectedImage shows confirm modal for deletion
func (m Model) deleteSelectedImage() (tea.Model, tea.Cmd) {
	img := m.getSelectedImage()
	if img == nil {
		return m, nil
	}
	name := img.Name()
	if m.imageTable.IsBusy(img.ID) {
		return m, m.footer.Warn(busyMessage)
	}
	m.pendingAction = "delete-image"
	m.confirmModal = sharedcomponents.NewConfirmModal("Delete Image", fmt.Sprintf("Delete '%s'?", name))
	return m, nil
}

// pruneImages shows confirm modal for pruning
func (m Model) pruneImages() (tea.Model, tea.Cmd) {
	m.pendingAction = "prune-images"
	m.confirmModal = sharedcomponents.NewConfirmModal("Prune Images", "Remove all dangling (unused) images?")
	return m, nil
}

// scanSelectedImage launches a scan for the selected image using saved options
func (m Model) scanSelectedImage() (tea.Model, tea.Cmd) {
	img := m.getSelectedImage()
	if img == nil {
		return m, nil
	}
	name := img.Name()
	if m.scanningImage(name) {
		return m, m.footer.Warn("Scan already in progress")
	}
	return m, jobs.Start(
		m.scanRun([]string{name}),
		batchScanCmd([]imageScanJob{{Name: name, Target: img.ScanTarget()}}, scan.OptionsFromConfig(m.config)),
	)
}

// scanAllUnscanned triggers batch scanning of all unscanned images using config defaults
// confirmScanAll asks before scanning every image, and the purge is the modal's
// checkbox rather than a second key.
//
// A and ctrl+a differed only by a modifier, and nothing in their shape said
// which one purged the cache — the closest this application came to losing data
// by accident (§3.26). The destructive half is a deliberate gesture now.
func (m Model) confirmScanAll() (tea.Model, tea.Cmd) {
	if m.anyScanRunning() {
		return m, m.footer.Warn("A scan is already running")
	}
	m.scanAllModal = sharedcomponents.NewOptionConfirmModal(
		"Scan All",
		"Scan every image in this list?",
		"Purge cached results first (rescans everything)",
	)
	return m, nil
}

// scanAll scans the whole list when the cache was purged, and only what has
// never been scanned otherwise.
func (m Model) scanAll(purge bool) (tea.Model, tea.Cmd) {
	if purge {
		return m.requestScanAll()
	}
	return m.scanAllUnscanned()
}

func (m Model) scanAllUnscanned() (tea.Model, tea.Cmd) {
	if m.anyScanRunning() {
		return m, nil
	}
	var queue []imageScanJob
	for _, img := range m.images {
		if img.Repository == "<none>" {
			continue
		}
		name := img.Name()
		if _, ok := m.scanCache[name]; !ok {
			queue = append(queue, imageScanJob{Name: name, Target: img.ScanTarget()})
		}
	}
	if len(queue) == 0 {
		return m, m.footer.Warn("All images are already scanned")
	}
	return m, jobs.Start(
		m.scanRun(jobNames(queue)),
		batchScanCmd(queue, scan.OptionsFromConfig(m.config)),
	)
}

// requestScanAll launches a batch scan for all images with the configured options.
// Rule 126: purges the in-memory and disk cache before scanning.
func (m Model) requestScanAll() (tea.Model, tea.Cmd) {
	if m.anyScanRunning() {
		return m, nil
	}
	var queue []imageScanJob
	var cacheKeys []string
	for _, img := range m.images {
		if img.Repository == "<none>" {
			continue
		}
		name := img.Name()
		queue = append(queue, imageScanJob{Name: name, Target: img.ScanTarget()})
		cacheKeys = append(cacheKeys, name)
		delete(m.scanCache, name)
	}
	if len(queue) == 0 {
		return m, nil
	}
	return m, tea.Batch(
		deleteScanCacheCmd(cacheKeys),
		jobs.Start(m.scanRun(cacheKeys), batchScanCmd(queue, scan.OptionsFromConfig(m.config))),
	)
}

// handleImageScanStarting drops whatever the footer still said about the last
// attempt.
//
// The row is already spinning: the router recorded the transition before handing
// the message on, and the snapshot that carried it rebuilt the table. There is
// no chain to restart either — the router holds the only one (D5).
func (m Model) handleImageScanStarting(_ ImageScanStartingMsg) (tea.Model, tea.Cmd) {
	m.footer.Clear()
	return m, nil
}

// handleImageScanFinished updates scan results for a completed image scan.
func (m Model) handleImageScanFinished(msg ImageScanFinishedMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil {
		m.failedScans[msg.ImageName] = true
	} else {
		delete(m.failedScans, msg.ImageName)
		m.scanCache[msg.ImageName] = msg.Entry
		m.footer.Clear()
	}
	m.updateImageTable()
	if m.registryBrowser != nil {
		m.registryBrowser.SetScanCache(m.scanCache)
	}
	return m, nil
}

// handleScanRequest rescans one image by name, whoever asked.
//
// The router sends this when a cached scan's stored result has gone missing:
// the row is still in the list, and the scan that would replace it belongs
// here, next to the cache it writes. The name is both the cache key and the
// scan target, as it is for an image typed rather than picked.
func (m Model) handleScanRequest(msg ScanRequestMsg) (tea.Model, tea.Cmd) {
	if msg.ImageName == "" || m.scanningImage(msg.ImageName) {
		return m, nil
	}
	job := imageScanJob{Name: msg.ImageName, Target: msg.ImageName}
	return m, jobs.Start(
		m.scanRun([]string{msg.ImageName}),
		batchScanCmd([]imageScanJob{job}, scan.OptionsFromConfig(m.config)),
	)
}

// jobNames is the target list of a queue of scan jobs, in order.
func jobNames(queue []imageScanJob) []string {
	out := make([]string, 0, len(queue))
	for _, job := range queue {
		out = append(out, job.Name)
	}
	return out
}

package ociresources

import (
	"fmt"

	tea "github.com/charmbracelet/bubbletea"
)

// Rows an action is running on, across the four tabs (§3.22).
//
// Every action here is a `docker` invocation that can take seconds — removing a
// large image, a network the daemon is still tearing connections off, a
// `docker login` that has to reach a registry over a slow link. Nothing said so:
// the row was identical to one with nothing happening to it.
//
// Each table spends a different cell on the spinner, and the choice is the same
// each time: the one the user does not need while the action runs. §3.16 settled
// why it is a cell and not a column of its own — a column costs cells on every
// screen to say nothing on all but one row, and at 80 columns this view has none
// to spare.

// busyMessage is what every tab says when an action is already running on the
// selected row. One message rather than one per verb, because the user's next
// move is the same in all of them: wait.
const busyMessage = "Already busy — an action is running on this row"

// advanceBusySpinners moves every table's frame on and reports whether anything
// is running. It is called from the spinner tick, which is what keeps the frames
// turning; the tick has to go on being scheduled while this returns true, or the
// spinner stops on a row that is still working.
func (m *Model) advanceBusySpinners() bool {
	m.imageTable.AdvanceSpinner()
	m.networkTable.AdvanceSpinner()
	m.volumeTable.AdvanceSpinner()
	m.registryTable.AdvanceSpinner()
	return len(m.busyLabels()) > 0
}

// busyLabels gathers what is running across every tab.
//
// Across all four rather than the active one: an action started on the Images
// tab goes on running after `tab`, and a spinner that stopped turning because
// the user looked elsewhere would read as a hang on the way back.
func (m Model) busyLabels() []string {
	var out []string
	out = append(out, m.imageTable.BusyLabels()...)
	out = append(out, m.networkTable.BusyLabels()...)
	out = append(out, m.volumeTable.BusyLabels()...)
	out = append(out, m.registryTable.BusyLabels()...)
	return out
}

// actionLine names what is running, in words. The spinner on the row says that
// something is; this says what.
//
// Rendered from the current state rather than assigned to a footer message,
// because a footer message expires after three seconds (Rule 128) and these
// outlive that — the same reason §3.17's sync progress is a rendered line.
func (m Model) actionLine() string {
	if m.pruning != "" {
		return "Pruning " + m.pruning + "…"
	}
	labels := m.busyLabels()
	switch len(labels) {
	case 0:
		return ""
	case 1:
		return labels[0] + "…"
	default:
		// Naming them all would run past the line; the count is what the user
		// is waiting on anyway.
		return fmt.Sprintf("%d actions running…", len(labels))
	}
}

// busyTick is what an action returns alongside its command so the frames turn.
// Init starts a tick, but it stops as soon as nothing is loading, and an action
// begun after that would sit on a frozen frame.
func (m Model) busyTick() tea.Cmd { return m.spinner.Tick }

package ociresources

import (
	"context"

	"time"

	"github.com/charmbracelet/bubbles/spinner"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/registrymgr"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ociTab represents the active tab in the OCI resources view
type ociTab int

const (
	tabImages     ociTab = iota
	tabNetworks          // Networks tab
	tabVolumes           // Volumes tab
	tabRegistries        // Registries tab
)

// Model represents the OCI resources view state
type Model struct {
	config    *config.Config
	activeTab ociTab
	// Images tab
	images    []docker.Image
	scanCache map[string]cache.ImageScanEntry
	// jobs is the router snapshot of everything running anywhere, and jobFrame
	// the spinner frame that goes with it — bare, because it lands in a table
	// cell (Rule 122). It replaced a scanningImages map and the `scanning`
	// bool derived from it, both of which knew only what this view launched.
	//
	// spinnerFrameIdx below stays: it animates *loading*, and a load is not a
	// job. See jobs.go.
	jobs            []jobs.Run
	jobFrame        string
	failedScans     map[string]bool
	spinnerFrameIdx int
	imageTable      datatable.Model[imageRow]
	spinner         spinner.Model
	loading         bool
	// Networks tab

	networkTable datatable.Model[docker.Network]
	loadingNets  bool
	// Volumes tab

	volumeTable datatable.Model[docker.Volume]
	loadingVols bool
	// Registries tab
	registries          []config.RegistryItem
	registryTable       datatable.Model[registryRow]
	loadingRegs         bool
	registryForm        *RegistryForm
	registryBrowser     *RegistryBrowser
	registryLoginStatus map[string]bool // URL → logged in
	// groupCache is what the Members column reads: slug → last discovery. It is
	// loaded from disk once and updated as discoveries come back.
	groupCache map[string]cache.RegistryGroupEntry
	// refreshingGroups holds the slugs a discovery is running for, so ctrl+r on
	// a row already refreshing does not fire a second one.
	refreshingGroups map[string]bool
	// browserDeselected holds the keys of the entries the user unchecked in the
	// registry browser, kept so the next open starts where the last one left
	// off. Keyed on the browser's entry key rather than a URL — see
	// browserRegistryEntry.key (D40).
	browserDeselected map[string]bool
	// registryGroupSlug is the group the Registries tab has drilled into, empty
	// at the top level.
	registryGroupSlug string
	// launch options pending save — set on submit, cleared after successful or failed launch
	lastLaunchImage string
	lastLaunchOpts  *cache.LaunchOptionsEntry
	// Forms (viewport-based, Rule 112)
	launchForm         *LaunchForm
	resourceForm       *ResourceCreateForm
	networkInspectForm *NetworkInspectForm
	connectivityForm   *ConnectivityTestForm
	// pruning names what a prune is working on, empty when none is. A prune
	// acts on no row — marking every row would say something false — so it gets
	// a footer line of its own instead.
	pruning string
	// Shared state
	// footer is the one line of transient state below the tab bar (Rule 128).
	footer        sharedcomponents.FooterMessage
	confirmModal  *sharedcomponents.ConfirmModal
	pendingAction string
	// scanAllModal carries A's purge checkbox. Separate from confirmModal
	// because the two answer different messages, and one field holding either
	// would make the handler guess which question was asked.
	scanAllModal  *sharedcomponents.OptionConfirmModal
	width, height int
}

// Messages — Images

// ImageScanStartingMsg signals that scanning is starting for a single image
type ImageScanStartingMsg struct {
	ImageName string

	// Cancel stops the scan, and is what makes `K` on this row mean anything
	// (D7). It rides on the starting message because the context is created
	// inside the Cmd: the registry stores it in the same Update that marks the
	// item running, so there is no window where the row is running and cannot
	// be stopped.
	Cancel context.CancelFunc
}

// ImageScanFinishedMsg signals that scanning has completed for a single image
type ImageScanFinishedMsg struct {
	ImageName string
	Entry     cache.ImageScanEntry
	Err       error
}

// RefreshTickMsg triggers periodic refresh
type RefreshTickMsg time.Time

// ImagesListMsg contains fetched images
type ImagesListMsg struct {
	Images []docker.Image
	Err    error
}

// ImageActionMsg signals result of an image action (remove).
//
// ID used to hold the image *reference*, not its ID: removeImageCmd filled it
// from its `name` argument. Nothing caught it because the only reader was a log
// line. It matters now — the busy marker is keyed on the ID, so a message
// carrying a name would never lift it and the row would spin for good.
type ImageActionMsg struct {
	Action string
	ID     string
	Name   string
	Err    error
}

// PruneCompleteMsg signals result of image prune
type PruneCompleteMsg struct {
	Output string
	Err    error
}

// ScanRequestMsg is sent when user requests a security scan on a single image
type ScanRequestMsg struct {
	ImageName string
}

// ScanAllRequestMsg is sent when user wants to scan all unscanned images
type ScanAllRequestMsg struct {
	ImageNames []string
}

// ScanCacheLoadedMsg contains the loaded scan cache
type ScanCacheLoadedMsg struct {
	Entries map[string]cache.ImageScanEntry
}

// ScanDetailsRequestMsg is sent when the user wants to view cached scan details for a specific image
type ScanDetailsRequestMsg struct {
	ImageName string
}

// Messages — Network Diagnostics

// NetworkInspectLoadedMsg contains the result of inspecting a network
type NetworkInspectLoadedMsg struct {
	NetworkID   string
	NetworkName string
	Containers  []docker.NetworkContainer
	Err         error
}

// DiagnosticTestCompleteMsg contains the result of a connectivity test
type DiagnosticTestCompleteMsg struct {
	Output string
	Err    error
}

// Messages — Networks

// NetworksListMsg contains fetched networks
type NetworksListMsg struct {
	Networks []docker.Network
	Err      error
}

// NetworkActionMsg signals result of a network action.
//
// ID names which network it was. The message carried no identity at all, which
// was survivable while the only thing it did was refetch the list — a busy
// marker has to be lifted from the row it was put on.
type NetworkActionMsg struct {
	Action string
	ID     string
	Err    error
}

// NetworkPruneCompleteMsg signals result of network prune
type NetworkPruneCompleteMsg struct {
	Output string
	Err    error
}

// Messages — Volumes

// VolumesListMsg contains fetched volumes
type VolumesListMsg struct {
	Volumes []docker.Volume
	Err     error
}

// VolumeActionMsg signals result of a volume action.
//
// Name is a volume's identity — it has no ID of its own. Same reason as
// NetworkActionMsg: the message carried nothing to lift a marker from.
type VolumeActionMsg struct {
	Action string
	Name   string
	Err    error
}

// VolumePruneCompleteMsg signals result of volume prune
type VolumePruneCompleteMsg struct {
	Output string
	Err    error
}

// Messages — Registry Browser

// MultiRegistryTag represents a single tag result from one registry.
//
// EntryKey is what the result is attributed by. RegistryURL no longer
// identifies anything on its own: several entries share one host once a
// registry is an address — a host plus a repo prefix — rather than a URL
// (§3.18). It is kept because it is what the pull reference is built from.
// Repo already carries the prefix, applied once in submitSearch.
type MultiRegistryTag struct {
	EntryKey    string
	RegistryURL string
	Alias       string
	Repo        string
	Tag         string
	UpdatedAt   time.Time
}

// MultiRegistryTagsLoadedMsg carries the tag list from one registry search.
type MultiRegistryTagsLoadedMsg struct {
	EntryKey    string
	RegistryURL string
	Alias       string
	Repo        string
	Tags        []string
	Err         error
}

// MultiRegistryTagsMetaMsg carries last-updated times for tags from one registry (background enrichment).
type MultiRegistryTagsMetaMsg struct {
	EntryKey    string
	RegistryURL string
	Repo        string
	Meta        map[string]time.Time
	Err         error
}

// RegistryPullCompleteMsg signals the result of a docker pull initiated from the browser.
type RegistryPullCompleteMsg struct {
	ImageName string
	Err       error
}

// RegistryTagDirectScanMsg requests a direct remote scan of a registry image tag (no pull).
type RegistryTagDirectScanMsg struct {
	ImageName string
}

// RegistryGroupDetectedMsg carries the result of a group detection for one registry.
// Members is nil when the registry is not a group or detection failed.
//
// Slug is what the cache and the table are keyed on; RegistryURL is what the
// browser still matches on. Two registries configured with the same URL collide
// there — the slug is the natural key, and step 6 is where the browser moves to
// it (D13's second half).
type RegistryGroupDetectedMsg struct {
	RegistryURL string
	Slug        string
	Members     []registrymgr.GroupMember
	Err         error
}

// RegistryGroupCacheLoadedMsg carries every cached group discovery, keyed by
// group slug.
type RegistryGroupCacheLoadedMsg struct {
	Entries map[string]cache.RegistryGroupEntry
}

// BrowserSelectionLoadedMsg carries the registries this context had left
// unchecked in the browser.
type BrowserSelectionLoadedMsg struct {
	Deselected map[string]bool
}

// Messages — Registries

// RegistryLoginCompleteMsg signals result of a docker login operation
type RegistryLoginCompleteMsg struct {
	RegistryURL string
	Err         error
}

// RegistryLogoutCompleteMsg signals result of a docker logout operation
type RegistryLogoutCompleteMsg struct {
	RegistryURL string
	Err         error
}

// RegistryLoginStatusMsg carries the login status for all configured registries
type RegistryLoginStatusMsg struct {
	Status map[string]bool // URL → logged in
}

// Messages — Container launch

// LaunchOptionsCacheLoadedMsg contains cached launch options for an image.
// Entry is nil when no cached options exist for the image.
type LaunchOptionsCacheLoadedMsg struct {
	ImageName string
	Entry     *cache.LaunchOptionsEntry
}

// ClipboardCopyMsg signals the result of a clipboard copy operation
type ClipboardCopyMsg struct {
	Err error
}

// ImageExposedPortsMsg contains exposed ports fetched from an image
type ImageExposedPortsMsg struct {
	ImageName string
	Ports     []string
	Err       error
}

// ContainerLaunchCompleteMsg signals result of launching a container
type ContainerLaunchCompleteMsg struct {
	ContainerID string
	Err         error
}

// New creates a new OCI resources view
func New(cfg *config.Config) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	it := datatable.New(datatable.Config[imageRow]{
		Columns:    imageColumns(),
		SortColumn: imageColumnName,
		Key:        func(r imageRow) string { return r.Image.ID },
		// The ID cell, not a column of its own. §3.16 settled that argument for
		// the clone checkbox: a column costs cells on every screen to say
		// nothing on all but one row, and at 80 columns this view has none to
		// spare. The ID is the cell to spend — it neither sorts nor searches,
		// twelve hex characters being nothing anyone orders or looks for, and
		// it is not what the user is watching while the image is removed.
		StatusColumn: imageColumnID,
	})

	nt := datatable.New(datatable.Config[docker.Network]{
		Columns:      networkColumns(),
		SortColumn:   -1,
		Key:          func(n docker.Network) string { return n.ID },
		StatusColumn: networkColumnID,
	})
	nt.Blur()

	vt := datatable.New(datatable.Config[docker.Volume]{
		Columns:    volumeColumns(),
		SortColumn: -1,
		// A volume has no ID: its name is its identity, which is also why the
		// spinner cannot go there — it is the one cell that says which row this
		// is. Driver is the expendable one, and it reads "local" on very nearly
		// every volume there has ever been.
		Key:          func(v docker.Volume) string { return v.Name },
		StatusColumn: volumeColumnDriver,
	})
	vt.Blur()

	rt := datatable.New(datatable.Config[registryRow]{
		Columns:    registryColumns(),
		SortColumn: -1,
		// The URL, because that is what docker keys a login on and what
		// RegistryLoginCompleteMsg carries back. Two entries declared on one
		// host therefore spin together — which is right: one `docker login`
		// really does change the answer for both. This is the one place D40's
		// rule does not apply, and it does not apply because the *operation* is
		// host-scoped, not because the identity is convenient.
		Key: func(r registryRow) string { return r.url },
		// Logged is the cell a login is about to change, so it is the one to
		// spend while it runs.
		StatusColumn: registryColumnLogged,
	})
	rt.Blur()

	return Model{
		config:              cfg,
		activeTab:           tabImages,
		scanCache:           make(map[string]cache.ImageScanEntry),
		failedScans:         make(map[string]bool),
		spinner:             s,
		imageTable:          it,
		networkTable:        nt,
		volumeTable:         vt,
		registryTable:       rt,
		registries:          cfg.Registry.Registries,
		registryLoginStatus: make(map[string]bool),
		groupCache:          make(map[string]cache.RegistryGroupEntry),
		refreshingGroups:    make(map[string]bool),
		browserDeselected:   make(map[string]bool),
		loading:             true,
		loadingNets:         true,
		loadingVols:         true,
	}
}

package ociresources

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/registryalias"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// imageRow is one line of the Images tab: the image, plus everything the row
// says about it that does not live on the image — the cached scan counts,
// whether a scan is running or the last one failed, and the alias-substituted
// name.
//
// The columns are built once, in New, so their Cell functions cannot reach back
// into the model for any of that. Carrying it on the row instead is what keeps
// the sort honest: the C column orders by the same number it prints, where the
// old comparator looked the entry up a second time.
type imageRow struct {
	Image        docker.Image
	DisplayName  string
	RawName      string
	Entry        cache.ImageScanEntry
	Scanned      bool
	Scanning     bool
	Failed       bool
	SpinnerFrame string
}

// The columns something else refers to. imageColumnID is where a running action
// puts its spinner; imageColumnName is what the tab opens sorted by.
const (
	imageColumnID   = 0
	imageColumnName = 1
)

// secretsColumnWidth is the Secrets column, at the width the workspaces list
// gives it. Elle ne trie pas, comme là-bas : `datatable` réserve deux cellules
// de plus à une colonne triable pour sa flèche, ce qui est cher pour un glyphe.
const secretsColumnWidth = 7

// secrets is the row's verdict — inconnu tant que l'image n'a pas été scannée,
// et inconnu aussi pour un scan qui n'a pas eu d'étape secrets.
func (r imageRow) secrets() theme.SecretsState {
	return theme.SecretsVerdict(r.Entry.Sensitive, r.Scanned)
}

// cveColumn builds one of the four severity count columns.
//
// severity names the column's level for the colour, spelled as the scanners
// spell it — the title here is a single letter, which is no basis for deciding
// what colour a count is.
func cveColumn(title, severity string, get func(cache.ImageScanEntry) int) datatable.Column[imageRow] {
	return datatable.Column[imageRow]{
		Title: title, Sizing: datatable.SizingFixed, MinWidth: 4,
		Cell: func(r imageRow) string { return formatCVECount(get(r.Entry), r.Scanned) },
		// A zero is dim, like an unscanned image: four coloured zeroes on a
		// clean image would read as four findings.
		Style: func(r imageRow) lipgloss.Style {
			if !r.Scanned || get(r.Entry) == 0 {
				return theme.DimStyle
			}
			return theme.SeverityTextStyle(severity)
		},
		Less: func(a, b imageRow) bool { return get(a.Entry) < get(b.Entry) },
	}
}

// scannedStyle colours the scan state, a failure being the one value in the
// column that asks for anything.
func scannedStyle(r imageRow) lipgloss.Style {
	switch {
	case r.Failed:
		return theme.StatusErrorStyle
	case r.Scanning, !r.Scanned:
		return theme.DimStyle
	}
	// Aucune opinion : c'est la table qui pose la couleur de texte du thème.
	return lipgloss.NewStyle()
}

// scannedCell reports the scan state: the spinner while one runs, an error icon
// when the last attempt failed, otherwise how long ago it succeeded.
func scannedCell(r imageRow) string {
	switch {
	case r.Scanning:
		return r.SpinnerFrame + "scanning"
	case r.Failed:
		return theme.IconError + " error"
	case r.Scanned:
		return timeAgo(r.Entry.ScannedAt)
	}
	return "-"
}

// imageColumns describes the Images tab. ID is the only column that neither
// sorts nor searches — twelve hex characters are not something anyone orders or
// looks for.
func imageColumns() []datatable.Column[imageRow] {
	return []datatable.Column[imageRow]{
		{
			Title: "ID", Sizing: datatable.SizingFixed, MinWidth: 14,
			Cell: func(r imageRow) string { return shortID(r.Image.ID) },
		},
		{
			Title: "Name", Sizing: datatable.SizingContent,
			MinWidth: 20, MaxWidth: 48, Flex: 1, TruncateHead: true,
			Cell: func(r imageRow) string { return r.DisplayName },
			Less: func(a, b imageRow) bool { return strings.ToLower(a.RawName) < strings.ToLower(b.RawName) },
			// Both names. The filter has always matched the repository and tag
			// docker reports; the alias the row actually shows was not
			// searchable, which is a small thing that reads as a bug when the
			// column says one name and the query wants the other.
			Search: func(r imageRow) string { return r.DisplayName + " " + r.RawName },
		},
		{
			Title: "Disk Usage", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12,
			Cell: func(r imageRow) string { return formatBytes(r.Image.UniqueSize) },
			Less: func(a, b imageRow) bool { return a.Image.UniqueSize < b.Image.UniqueSize },
		},
		{
			Title: "Content Size", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 14,
			Cell: func(r imageRow) string { return formatBytes(r.Image.Size) },
			Less: func(a, b imageRow) bool { return a.Image.Size < b.Image.Size },
		},
		{
			Title: "Secrets", Sizing: datatable.SizingFixed, MinWidth: secretsColumnWidth,
			Cell:  func(r imageRow) string { return theme.SecretsIcon(r.secrets()) },
			Style: func(r imageRow) lipgloss.Style { return theme.SecretsStyle(r.secrets()) },
		},
		cveColumn("C", "CRITICAL", func(e cache.ImageScanEntry) int { return e.Critical }),
		cveColumn("H", "HIGH", func(e cache.ImageScanEntry) int { return e.High }),
		cveColumn("M", "MEDIUM", func(e cache.ImageScanEntry) int { return e.Medium }),
		cveColumn("L", "LOW", func(e cache.ImageScanEntry) int { return e.Low }),
		{
			Title: "Scanned", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 14,
			Cell:  scannedCell,
			Style: scannedStyle,
			Less:  func(a, b imageRow) bool { return a.Entry.ScannedAt.Before(b.Entry.ScannedAt) },
		},
	}
}

// imageRows decorates the image list with the scan state the table shows.
func (m *Model) imageRows() []imageRow {
	aliases := registryalias.From(m.registries)
	// The scan frame comes from the registry, which holds the one chain that
	// animates work (D5). spinnerFrameIdx below is local, and it animates
	// loading — a load is not a job.
	frame := m.jobFrame
	scanning := m.scanningNames()

	rows := make([]imageRow, 0, len(m.images))
	for _, img := range m.images {
		raw := img.Name()
		entry, scanned := m.scanCache[raw]
		rows = append(rows, imageRow{
			Image:        img,
			DisplayName:  docker.ApplyAliases(raw, aliases),
			RawName:      raw,
			Entry:        entry,
			Scanned:      scanned,
			Scanning:     scanning[raw],
			Failed:       m.failedScans[raw],
			SpinnerFrame: frame,
		})
	}
	return rows
}

// formatBytes formats bytes into human-readable string
func formatBytes(b int64) string {
	switch {
	case b >= 1e9:
		return fmt.Sprintf("%.1f GB", float64(b)/1e9)
	case b >= 1e6:
		return fmt.Sprintf("%.1f MB", float64(b)/1e6)
	case b >= 1e3:
		return fmt.Sprintf("%.1f kB", float64(b)/1e3)
	default:
		return fmt.Sprintf("%d B", b)
	}
}

// formatCVECount formats a CVE count for display, returns "-" if not scanned
func formatCVECount(count int, scanned bool) string {
	if !scanned {
		return "-"
	}
	return fmt.Sprintf("%d", count)
}

// updateImageTable rebuilds the image table rows.
//
// Every caller reaches here after changing something the row shows — a scan
// started, finished, or the list came back — so the decoration is recomputed
// wholesale rather than patched in place.
func (m *Model) updateImageTable() {
	m.imageTable.SetItems(m.imageRows())
	m.imageTable.SetHeight(m.tableHeight())
}

// networkColumnID and volumeColumnDriver are where a running action puts its
// spinner — the cell each table can spare while one row is being removed.
const (
	networkColumnID    = 0
	volumeColumnDriver = 1
)

// networkColumns describes the Networks tab. Neither this table nor the volumes
// one sorts or filters today, so no Less and no Search: `/` and `.` stay inert
// rather than being wired to a bar this view's footer does not render.
func networkColumns() []datatable.Column[docker.Network] {
	return []datatable.Column[docker.Network]{
		{Title: "ID", Sizing: datatable.SizingFixed, MinWidth: 14, Cell: func(n docker.Network) string { return shortID(n.ID) }},
		{Title: "Name", Sizing: datatable.SizingContent, MinWidth: 20, Flex: 1, Cell: func(n docker.Network) string { return n.Name }},
		{Title: "Driver", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12, Cell: func(n docker.Network) string { return n.Driver }},
		{Title: "Scope", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 10, Cell: func(n docker.Network) string { return n.Scope }},
	}
}

// volumeColumns describes the Volumes tab.
func volumeColumns() []datatable.Column[docker.Volume] {
	return []datatable.Column[docker.Volume]{
		{Title: "Name", Sizing: datatable.SizingContent, MinWidth: 20, Cell: func(v docker.Volume) string { return v.Name }},
		{Title: "Driver", Sizing: datatable.SizingFixed, MinWidth: 12, Cell: func(v docker.Volume) string { return v.Driver }},
		{Title: "Mountpoint", Sizing: datatable.SizingContent, Optional: true, TruncateHead: true, MinWidth: 20, Flex: 1, Cell: func(v docker.Volume) string { return v.Mountpoint }},
	}
}

// shortID truncates a Docker ID to the twelve characters the CLI shows.
func shortID(id string) string {
	if len(id) > 12 {
		return id[:12]
	}
	return id
}

// registryRow is one line of the Registries tab.
//
// The tab shows two populations in one table — the configured entries at the
// top level, and one group's discovered members after `→` — and datatable is
// generic over a single T, so the row type has to carry both. explorerRow
// exists for the same reason.
//
// config is the index into Model.registries the row stands for, and -1 for a
// discovered member: a member is not a config entry, has no alias of its own to
// edit and no credentials but its group's, so every action on the tab has to be
// able to tell the two apart. Carrying it on the row is also what lets the
// cursor be resolved without indexing m.registries by row number, which is
// correct today only because this table neither sorts nor filters.
type registryRow struct {
	alias   string
	url     string
	kind    string
	auth    string
	logged  string
	members string
	config  int
}

// registryColumnLogged is the cell a login or logout replaces with its spinner:
// it is precisely the answer the operation is about to change.
const registryColumnLogged = 4

// registryColumns describes the Registries tab. Nothing sorts or searches: the
// list is the order the config declares, which is the order the user wrote.
func registryColumns() []datatable.Column[registryRow] {
	return []datatable.Column[registryRow]{
		{Title: "Alias", Sizing: datatable.SizingContent, MinWidth: 16, Cell: func(r registryRow) string { return r.alias }},
		{Title: "URL", Sizing: datatable.SizingContent, TruncateHead: true, MinWidth: 20, Flex: 1, Cell: func(r registryRow) string { return r.url }},
		{Title: "Kind", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 10, Cell: func(r registryRow) string { return r.kind }},
		{Title: "Auth", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12, Cell: func(r registryRow) string { return r.auth }}, // holds "credentials"
		{Title: "Logged", Sizing: datatable.SizingFixed, MinWidth: 8, Cell: func(r registryRow) string { return r.logged }},
		{Title: "Members", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 16, Cell: func(r registryRow) string { return r.members }}, // holds "12 · 30 days ago"
	}
}

// registryRef is what an entry is displayed as: its address, not its URL.
//
// The prefix has to be on screen or the tab says nothing useful — one line per
// proxy is one host repeated, and a group's members all answer to the same host
// too (§3.18). Joined with a slash because that is exactly the head of the pull
// reference: `docker pull nexus.example.com/dhi-io-proxy/eclipse-temurin:21`.
// Plain text only — Rule 122.
func registryRef(url, repoPrefix string) string {
	if repoPrefix == "" {
		return url
	}
	return strings.TrimSuffix(url, "/") + "/" + repoPrefix
}

// membersCell reports what the last discovery for a group found, and when.
//
// The "when" is not decoration: a cache with no visible age is worse than the
// re-detection it replaced, because it looks current whatever it holds
// (§3.8, decision 3). Plain text only — Rule 122.
func (m *Model) membersCell(reg config.RegistryItem) string {
	if reg.Kind != config.KindGroup {
		return ""
	}
	if m.refreshingGroups[reg.Slug] {
		// The spinner's frame, not its View(): the latter renders through a
		// style, and a table cell carries no escape sequence.
		return spinner.Dot.Frames[m.spinnerFrameIdx%len(spinner.Dot.Frames)] + " refreshing"
	}
	entry, ok := m.groupCache[reg.Slug]
	if !ok {
		return "never" // declared a group, never asked
	}
	return fmt.Sprintf("%d · %s", len(entry.Members), timeAgo(entry.DiscoveredAt))
}

// loggedCell reports the docker login status for a registry URL.
func (m *Model) loggedCell(mode, url string) string {
	if !config.UsesCredentials(mode) {
		return "-"
	}
	if m.registryLoginStatus[url] {
		return theme.IconOK
	}
	return theme.IconError
}

// drilledGroup returns the group the tab has entered, or nil at the top level.
func (m *Model) drilledGroup() *config.RegistryItem {
	if m.registryGroupSlug == "" {
		return nil
	}
	for i := range m.registries {
		if m.registries[i].Slug == m.registryGroupSlug {
			return &m.registries[i]
		}
	}
	return nil
}

func (m *Model) updateRegistryTable() {
	if group := m.drilledGroup(); group != nil {
		m.updateGroupMemberTable(*group)
		return
	}
	rows := make([]registryRow, 0, len(m.registries))
	for i, reg := range m.registries {
		rows = append(rows, registryRow{
			alias:   reg.Alias,
			url:     registryRef(reg.URL, reg.RepoPrefix),
			kind:    reg.Kind,
			auth:    reg.AuthMode,
			logged:  m.loggedCell(reg.AuthMode, reg.URL),
			members: m.membersCell(reg),
			config:  i,
		})
	}
	m.setRegistryRows(rows)
}

// updateGroupMemberTable fills the table with one group's discovered members.
//
// A member is not a config entry: it has no alias of its own to edit, its
// credentials are the group's, and it is what the cache holds — so the columns
// say `inherit`, carry no member count, and the row points at no config entry.
func (m *Model) updateGroupMemberTable(group config.RegistryItem) {
	entry := m.groupCache[group.Slug]
	rows := make([]registryRow, 0, len(entry.Members))
	for _, member := range entry.Members {
		rows = append(rows, registryRow{
			alias:  member.Alias,
			url:    registryRef(member.URL, member.RepoPrefix),
			kind:   "member",
			auth:   config.AuthInherit,
			logged: m.loggedCell(group.AuthMode, group.URL),
			config: -1,
		})
	}
	m.setRegistryRows(rows)
}

func (m *Model) setRegistryRows(rows []registryRow) {
	m.registryTable.SetItems(rows)
	m.registryTable.Resize(m.width, m.tableHeight())
}

